program='''def transform(grid):
    h = len(grid)
    w = len(grid[0])
    marker = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    # The rare color marks line segments; fill between its outermost markers on each row and column.
    # ARC inputs use a two-color field, with the more frequent color as background.
    colors = {}
    for row in grid:
        for v in row:
            colors[v] = colors.get(v, 0) + 1
    marker = min(colors, key=colors.get)
    out = [row[:] for row in grid]
    for r, row in enumerate(grid):
        cols = [c for c, v in enumerate(row) if v == marker]
        if cols:
            for c in range(min(cols), max(cols) + 1):
                if grid[r][c] != marker:
                    out[r][c] = 3
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == marker]
        if rows:
            for r in range(min(rows), max(rows) + 1):
                if grid[r][c] != marker:
                    out[r][c] = 3
    return out
'''
